int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // adjacency list: for each station, list of (neighbor, company)
    vector<vector<pair<int,int>>> adj(N + 1);
    for (int i = 0; i < M; i++) {
        int p, q, c;
        cin >> p >> q >> c;
        adj[p].push_back({q, c});
        adj[q].push_back({p, c});
    }

    // dist[station][company] -> minimum cost to reach station using that company last
    // We'll compress company IDs into indices.
    map<int, int> compId;
    int id = 0;
    for (int u = 1; u <= N; u++) {
        for (auto &v : adj[u]) {
            int c = v.second;
            if (!compId.count(c)) compId[c] = id++;
        }
    }
    int C = compId.size();

    const int INF = 1e9;
    vector<vector<int>> dist(N + 1, vector<int>(C, INF));
    deque<pair<int,int>> dq; // (station, companyId)

    // Starting: board any company from station 1 at cost 1
    for (auto &v : adj[1]) {
        int comp = compId[v.second];
        if (dist[1][comp] > 1) {
            dist[1][comp] = 1;
            dq.push_back({1, comp});
        }
    }

    // 0-1 BFS
    while (!dq.empty()) {
        auto [u, c] = dq.front(); dq.pop_front();
        int d = dist[u][c];

        for (auto &v : adj[u]) {
            int to = v.first;
            int nc = compId[v.second];
            int nd = d + (nc != c ? 1 : 0);
            if (nd < dist[to][nc]) {
                dist[to][nc] = nd;
                if (nc == c) dq.push_front({to, nc});
                else dq.push_back({to, nc});
            }
        }
    }

    int ans = INF;
    for (int c = 0; c < C; c++) ans = min(ans, dist[N][c]);
    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

