    // cost to be at station using last company
    const int INF = 1e9;
    vector<vector<int>> dist(N+1, vector<int>(maxC+1, INF));

    // priority queue: (cost, station, company)
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;

    // Start at station 1 with no company (company = 0), cost = 0
    // We handle company=0 specially
    // dist[1][0] = 0 means we're at station 1, haven't used any company
    // But we need dist for company 0 too
    vector<int> dist0(N+1, INF); // dist with "no company"
    dist0[1] = 0;
    pq.push({0, 1, 0}); // cost, station, company (0 = none)

    while (!pq.empty()) {
        auto [d, u, c] = pq.top(); pq.pop();

        int cur_dist = (c == 0) ? dist0[u] : dist[u][c];
