        for (auto [v, nc] : adj[u]) {
            int nd;
            if (c == nc) {
                nd = d; // same company, no extra cost
            } else {
                nd = d + 1; // switch company (or start using first company)
            }

            if (nd < dist[v][nc]) {
                dist[v][nc] = nd;
                pq.push({nd, v, nc});
            }
        }
    }

    int ans = INF;
    for (int c = 1; c <= maxC; c++) {
        ans = min(ans, dist[N][c]);
    }

