    inputEdges.reserve(M);

    for (int i = 0; i < M; i++) {
        int p, q, c;
        cin >> p >> q >> c;
        inputEdges.emplace_back(p, q, c);
        compsAtStation[p].push_back(c);
        compsAtStation[q].push_back(c);
    }

    // Compress nodes of form (station, company) into ids.
    // Also create one node per station.
    // Graph construction:
    // station -> (station, company) cost 1   (start using that company)
    // (station, company) -> station cost 0   (stop there, no extra cost)
    // (u, company) <-> (v, company) cost 0   (ride within same company)
    //
    // Then answer is shortest distance from station 1 node to station N node.

    vector<int> stationNode(N + 1);
    int id = 0;
    for (int i = 1; i <= N; i++) stationNode[i] = id++;

    vector<unordered_map<int,int>> mp(N + 1);
    for (int i = 1; i <= N; i++) {
        auto &v = compsAtStation[i];
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        mp[i].reserve(v.size() * 2 + 1);
        for (int c : v) {
            mp[i][c] = id++;
        }
    }

    vector<vector<pair<int,int>>> g(id);

    for (int i = 1; i <= N; i++) {
        for (auto &kv : mp[i]) {
            int node = kv.second;
            g[stationNode[i]].push_back({node, 1});
            g[node].push_back({stationNode[i], 0});
        }
    }

    for (auto &[p, q, c] : inputEdges) {
        int u = mp[p][c];
        int v = mp[q][c];
        g[u].push_back({v, 0});
        g[v].push_back({u, 0});
    }

    const int INF = 1e9;
    vector<int> dist(id, INF);
    deque<int> dq;

    dist[stationNode[1]] = 0;
    dq.push_back(stationNode[1]);

    while (!dq.empty()) {
        int v = dq.front();
        dq.pop_front();

        for (auto &[to, w] : g[v]) {
            if (dist[to] > dist[v] + w) {
                dist[to] = dist[v] + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
    }

    int ans = dist[stationNode[N]];
    if (ans == INF) ans = -1;
    cout << ans << '\n';

    return 0;
}

