typedef long long ll;

typedef struct {
    int u, v, c;
} EdgeInput;

typedef struct {
    int to, next;
} Edge;

typedef struct {
    int station, company;
} Pair;

static int cmp_edge_input(const void *a, const void *b) {
    const EdgeInput *x = (const EdgeInput *)a;
    const EdgeInput *y = (const EdgeInput *)b;
    if (x->u != y->u) return x->u < y->u ? -1 : 1;
    if (x->c != y->c) return x->c < y->c ? -1 : 1;
    if (x->v != y->v) return x->v < y->v ? -1 : 1;
    return 0;
}

static int cmp_pair(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->station != y->station) return x->station < y->station ? -1 : 1;
    if (x->company != y->company) return x->company < y->company ? -1 : 1;
    return 0;
}

static int lower_bound_pair(Pair *arr, int n, int station, int company) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m].station < station || (arr[m].station == station && arr[m].company < company)) {
            l = m + 1;
        } else {
            r = m;
        }
    }
    return l;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    EdgeInput *in = (EdgeInput *)malloc(sizeof(EdgeInput) * M * 2);
    for (int i = 0; i < M; i++) {
        int p, q, c;
        scanf("%d %d %d", &p, &q, &c);
        in[2 * i] = (EdgeInput){p, q, c};
        in[2 * i + 1] = (EdgeInput){q, p, c};
    }

    qsort(in, 2 * M, sizeof(EdgeInput), cmp_edge_input);

    int max_groups = 2 * M;
    Pair *groups = (Pair *)malloc(sizeof(Pair) * max_groups);
    int G = 0;
    for (int i = 0; i < 2 * M; ) {
        int u = in[i].u, c = in[i].c;
        groups[G++] = (Pair){u, c};
        while (i < 2 * M && in[i].u == u && in[i].c == c) i++;
    }

    int total_nodes = 1 + G + N; 
    int *head = (int *)malloc(sizeof(int) * total_nodes);
    for (int i = 0; i < total_nodes; i++) head[i] = -1;

    ll max_edges = (ll)(2 * M) + (ll)(4 * G);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * max_edges);
    int ecnt = 0;

    #define ADD_EDGE(a,b) do { \
        edges[ecnt].to = (b); \
        edges[ecnt].next = head[(a)]; \
        head[(a)] = ecnt++; \
    } while (0)

    int *group_node_id = (int *)malloc(sizeof(int) * G);
    for (int i = 0; i < G; i++) group_node_id[i] = 1 + i;

    int station_base = 1 + G;
    for (int s = 1; s <= N; s++) {
        int station_node = station_base + (s - 1);
        (void)station_node;
    }

    for (int i = 0; i < G; i++) {
        int s = groups[i].station;
        int gnode = group_node_id[i];
        int snode = station_base + (s - 1);
        ADD_EDGE(snode, gnode); 
        ADD_EDGE(gnode, snode); 
    }

    for (int i = 0; i < 2 * M; i++) {
        int u = in[i].u, v = in[i].v, c = in[i].c;
        int idx1 = lower_bound_pair(groups, G, u, c);
        int idx2 = lower_bound_pair(groups, G, v, c);
        int g1 = group_node_id[idx1];
        int g2 = group_node_id[idx2];
        ADD_EDGE(g1, g2); 
    }

    int start = station_base + (1 - 1);
    int goal = station_base + (N - 1);

    const int INF = 1e9;
    int *dist = (int *)malloc(sizeof(int) * total_nodes);
    for (int i = 0; i < total_nodes; i++) dist[i] = INF;

    int *deque = (int *)malloc(sizeof(int) * (total_nodes * 2 + 5));
    int front = total_nodes, back = total_nodes;

    dist[start] = 0;
    deque[back++] = start;

    while (front < back) {
        int v = deque[front++];
        int dv = dist[v];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            int w;
            if (v >= station_base && to < station_base) w = 1; 
            else w = 0; 
            if (dist[to] > dv + w) {
                dist[to] = dv + w;
                if (w == 0) {
                    deque[--front] = to;
                } else {
                    deque[back++] = to;
                }
            }
        }
    }

    if (dist[goal] == INF) printf("-1\n");
    else printf("%d\n", dist[goal]);

    free(in);
    free(groups);
    free(head);
    free(edges);
    free(group_node_id);
    free(dist);
    free(deque);
    return 0;
}

