public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        // adjacency list: for each station, list of (neighbor, company)
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= N; i++) adj.add(new ArrayList<>());

        Set<Integer> companies = new HashSet<>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            adj.get(u).add(new int[]{v, c});
            adj.get(v).add(new int[]{u, c});
            companies.add(c);
        }

        // Compress company IDs
        // State: (station, company) where company=0 means "no company yet"
        // Map companies to 1..K, 0 = no company
        Map<Integer, Integer> compMap = new HashMap<>();
        int idx = 1;
        for (int c : companies) compMap.put(c, idx++);
        int K = idx; // number of companies + 1 (0 is "none")

        // dist[station][company] 
        int[][] dist = new int[N + 1][K];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);

        // PQ: (cost, station, company)
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dist[1][0] = 0;
        pq.offer(new int[]{0, 1, 0});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int cost = cur[0], u = cur[1], comp = cur[2];
            if (cost > dist[u][comp]) continue;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], c = compMap.get(edge[1]);
                int newCost;
                if (comp == 0) {
                    // first edge
                    newCost = cost + 1;
                } else if (comp == c) {
                    newCost = cost;
                } else {
                    newCost = cost + 1;
                }
                if (newCost < dist[v][c]) {
                    dist[v][c] = newCost;
                    pq.offer(new int[]{newCost, v, c});
                }
            }
        }

        int ans = Integer.MAX_VALUE;
        for (int c = 0; c < K; c++) {
            ans = Math.min(ans, dist[N][c]);
        }
        System.out.println(ans == Integer.MAX_VALUE ? -1 : ans);
    }
}

