            }

            for (Edge e : graph[station]) {
                int newCost = cost + (e.company == company ? 0 : 1);
                if (!dist[e.to].containsKey(e.company) || dist[e.to].get(e.company) > newCost) {
                    dist[e.to].put(e.company, newCost);
                    if (e.company == company) {
                        deque.addFirst(new int[]{e.to, e.company, newCost});
                    } else {
                        deque.addLast(new int[]{e.to, e.company, newCost});
                    }
                }
            }
        }

        System.out.println(answer == Integer.MAX_VALUE ? -1 : answer);
    }
}

import java.io.*;
import java.util.*;

/*
 * Snuke's subway:
 * - Moving along lines of the same company costs 1 yen total for that company segment.
 * - Each company change adds 1 yen.
 *
 * Model:
 * For each (station, company) pair that appears in input, create a node.
 * Also create a node for each station.
 *
 * Edges:
 * 1) station <-> (station, company) with costs:
 *      station -> (station, company): 1   (start using that company)
 *      (station, company) -> station: 0   (stop using that company)
 * 2) If a railway line connects u and v with company c:
 *      (u, c) <-> (v, c) with cost 0
 *
 * Then the answer is the shortest distance from station 1 node to station N node.
 * This is a 0-1 BFS graph.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    static long pack(int station, int company) {
        return (((long) station) << 32) ^ (company & 0xffffffffL);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        // station nodes: 0..N-1
        ArrayList<ArrayList<Edge>> g = new ArrayList<>();
        for (int i = 0; i < N; i++) g.add(new ArrayList<>());

        HashMap<Long, Integer> map = new HashMap<>();

        for (int i = 0; i < M; i++) {
            int p = fs.nextInt() - 1;
            int q = fs.nextInt() - 1;
            int c = fs.nextInt();

            long keyP = pack(p, c);
            Integer idP = map.get(keyP);
            if (idP == null) {
                idP = g.size();
                map.put(keyP, idP);
                g.add(new ArrayList<>());
                // station -> company-node : 1
                g.get(p).add(new Edge(idP, 1));
                // company-node -> station : 0
                g.get(idP).add(new Edge(p, 0));
            }

            long keyQ = pack(q, c);
            Integer idQ = map.get(keyQ);
            if (idQ == null) {
                idQ = g.size();
                map.put(keyQ, idQ);
                g.add(new ArrayList<>());
                g.get(q).add(new Edge(idQ, 1));
                g.get(idQ).add(new Edge(q, 0));
            }

            // same-company travel costs 0
            g.get(idP).add(new Edge(idQ, 0));
            g.get(idQ).add(new Edge(idP, 0));
        }

        int total = g.size();
        int[] dist = new int[total];
        Arrays.fill(dist, Integer.MAX_VALUE);

        Deque<Integer> dq = new ArrayDeque<>();
        dist[0] = 0; // station 1
        dq.addFirst(0);

        while (!dq.isEmpty()) {
            int v = dq.pollFirst();
            int dv = dist[v];
            for (Edge e : g.get(v)) {
                int nd = dv + e.cost;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    if (e.cost == 0) dq.addFirst(e.to);
                    else dq.addLast(e.to);
                }
            }
        }

        int ans = dist[N - 1];
        System.out.println(ans == Integer.MAX_VALUE ? -1 : ans);
    }
}
